import {subscriptionStatus} from './subscriptions.mjs';
export const durationUnits={year:'سنة',month:'شهر',week:'أسبوع',day:'يوم'};
export function invoiceText(i){return ['منصة العوائل · مطالبة سداد رقم '+i.number,'العائلة: '+i.tenant_name+' · الكود '+i.tenant_code,'الباقة: '+i.plan_name,'المدة: '+i.duration_count+' '+durationUnits[i.duration_unit],'الإجمالي: '+i.amount_sar+' ريال سعودي','الحالة: '+({issued:'بانتظار السداد',paid:'مسددة',void:'ملغاة'}[i.status]),'المدة تبدأ بعد السداد أو نهاية الاشتراك الساري.','هذه مطالبة سداد وليست فاتورة ضريبية.'].join('\n')}
export function invoiceEmail(i){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(i.contact_email||'')?'mailto:'+encodeURIComponent(i.contact_email)+'?subject='+encodeURIComponent('مطالبة اشتراك '+i.tenant_name+' رقم '+i.number)+'&body='+encodeURIComponent(invoiceText(i)):null}
export function invoiceWhatsApp(i){let phone=(i.contact_phone||'').replace(/\D/g,'');if(phone.startsWith('05'))phone='966'+phone.slice(1);return /^[1-9][0-9]{7,14}$/.test(phone)?'https://wa.me/'+phone+'?text='+encodeURIComponent(invoiceText(i)):null}
export function invoiceCard({i,element,button,busy,rpc,reload}){
 const card=element('article',undefined,'billing-invoice');card.append(element('h4','مطالبة #'+i.number),element('p',i.tenant_name+' · '+i.plan_name),element('strong',i.amount_sar+' ر.س'),element('p',({issued:'بانتظار السداد',paid:'مسددة',void:'ملغاة'}[i.status])),element('small','مطالبة سداد غير ضريبية. المشاركة تفتح رسالة جاهزة؛ لا تعني وصولها.'));
 for(const [label,url]of [['مشاركة بالبريد',invoiceEmail(i)],['مشاركة بواتساب',invoiceWhatsApp(i)]]){const a=element('a',label,'secondary');if(url){a.href=url;if(url.startsWith('https:')){a.target='_blank';a.rel='noopener noreferrer'}}else{a.setAttribute('aria-disabled','true');a.textContent=label+' · بيانات التواصل غير مكتملة'}card.append(a)}
 card.append(button('نسخ المطالبة',()=>navigator.clipboard.writeText(invoiceText(i)),'text-button'));
 if(i.status==='issued'){for(const [action,label]of [['invoice_paid','تسجيل استلام السداد وتجديد الاشتراك'],['invoice_void','إلغاء المطالبة']]){const b=button(label,()=>{const d=element('dialog');d.append(element('h3',label),element('p',i.tenant_name+' · '+i.amount_sar+' ر.س. لا يوجد تحصيل إلكتروني مفعّل.'));const yes=button('تأكيد',()=>busy(yes,async()=>{await rpc('platform_action',{action,data:{invoice:i.id,confirm:'MANUAL_PAYMENT_RECEIVED'}});d.close();d.remove();await reload()}),'primary');d.append(yes,button('إلغاء',()=>{d.close();d.remove()}));document.body.append(d);d.showModal()},'secondary');card.append(b)}}return card;
}
export async function showInvoices({container,tenant,element,button,busy,rpc}){const rows=await rpc('platform_action',{action:'invoices',data:tenant?{id:tenant}:{} });container.replaceChildren();for(const i of rows)container.append(invoiceCard({i,element,button,busy,rpc,reload:()=>showInvoices({container,tenant,element,button,busy,rpc})}));if(!rows.length)container.append(element('p','لا توجد مطالبات سداد.'))}
export function tenantBilling({t,plans,element,button,busy,rpc,toast,reload}){
 const box=element('section',undefined,'tenant-billing');box.append(element('h4','اشتراك الكيان'),element('p',subscriptionStatus(t)),element('p','اختر باقة من قائمة الاشتراكات الموحدة؛ تُنشأ مطالبة سداد تلقائيًا بعد تأكيد التعيين. لا تمتد المدة إلا بعد تسجيل السداد.'));const select=element('select');select.setAttribute('aria-label','باقة '+t.name);const empty=element('option','اختر الباقة');empty.value='';select.append(empty);for(const p of plans.filter(x=>x.enabled&&x.price_sar!=null)){const o=element('option',p.name+' · '+p.duration_count+' '+durationUnits[p.duration_unit]+' · '+p.price_sar+' ر.س');o.value=p.id;select.append(o)}select.value=t.billing_plan_id||'';box.append(select);
 const assign=button('تعيين الباقة وإنشاء المطالبة',()=>{if(!select.value)throw Error('أضف باقة مفعّلة ذات سعر من شاشة الاشتراكات أولًا.');const p=plans.find(p=>p.id===select.value),request_id=crypto.randomUUID(),d=element('dialog');d.append(element('h3','تأكيد تعيين الاشتراك'),element('p',t.name+' · '+p.name+' · '+p.price_sar+' ر.س'),element('p','تُلغى المطالبات السابقة غير المسددة فقط.'));const yes=button('تأكيد وإنشاء المطالبة',()=>busy(yes,async()=>{await rpc('platform_action',{action:'assign_plan',data:{id:t.id,plan_id:p.id,request_id}});d.close();d.remove();toast('أُنشئت مطالبة السداد.');await reload()}),'primary');d.append(yes,button('إلغاء',()=>{d.close();d.remove()}));document.body.append(d);d.showModal()},'primary');assign.disabled=!plans.some(p=>p.enabled&&p.price_sar!=null);box.append(assign);const list=element('div');box.append(button('عرض مطالبات الكيان',()=>showInvoices({container:list,tenant:t.id,element,button,busy,rpc}),'secondary'),list);return box;
}
export async function showPlans({container,element,button,busy,rpc,toast}){
 const rows=await rpc('platform_action',{action:'plans'});container.replaceChildren(element('h3','الباقات والاشتراكات'),element('p','عرّف المدد والأسعار هنا مرة واحدة، ثم اختر الباقة في كل كيان. تعديل السعر لا يغيّر المطالبات المنشأة سابقًا.'));
 for(const p of [{id:'',name:'',duration_count:1,duration_unit:'year',price_sar:'',enabled:false},...rows]){const form=element('form',undefined,'billing-plan');form.append(element('h4',p.id?'تعديل '+p.name:'باقة جديدة'));function field(name,label,type,value){const l=element('label',label),i=element('input');i.name=name;i.type=type;i.value=value??'';l.append(i);form.append(l);return i}field('name','اسم الباقة','text',p.name).required=true;const count=field('duration_count','المدة','number',p.duration_count);count.min=1;count.max=3650;count.required=true;count.step=1;const unit=element('select');unit.name='duration_unit';for(const [v,l]of Object.entries(durationUnits)){const o=element('option',l);o.value=v;unit.append(o)}unit.value=p.duration_unit;form.append(unit);const price=field('price_sar','السعر بالريال','number',p.price_sar);price.min=0;price.step='.01';price.max=99999999.99;const enabled=field('enabled','تفعيل الباقة','checkbox','');enabled.checked=p.enabled;const save=element('button','حفظ الباقة','primary');form.append(save);form.onsubmit=e=>{e.preventDefault();return busy(save,async()=>{await rpc('platform_action',{action:'plan_save',data:{id:p.id||null,name:form.elements.name.value.trim(),duration_count:Number(count.value),duration_unit:unit.value,price_sar:price.value||null,enabled:enabled.checked}});toast('حُفظت الباقة.');await showPlans({container,element,button,busy,rpc,toast})})};container.append(form)}
}
